const now = new Date();
const date = now.toISOString().slice(0, 10);
const token = $env.TELEGRAM_BOT_TOKEN || '';
const chatId = $env.TELEGRAM_CHAT_ID || '';
const telegramReady = Boolean(token && chatId && token !== 'REPLACE_ME' && chatId !== 'REPLACE_ME');
const youtube = $json.youtube || null;
const esc = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const totalsFromRows = (rows = []) => rows.reduce((acc, row) => {
  acc.views += Number(row[1] || 0);
  acc.likes += Number(row[2] || 0);
  acc.comments += Number(row[3] || 0);
  acc.subscribersGained += Number(row[4] || 0);
  return acc;
}, { views: 0, likes: 0, comments: 0, subscribersGained: 0 });

const sections = [
  '<b>Reporte conexiones y crecimiento - ' + date + '</b>',
  '',
  '<b>YouTube</b>'
];

const channels = youtube?.channels ? Object.values(youtube.channels) : (youtube?.channel ? [youtube] : []);
for (const channelReport of channels) {
  sections.push('');
  sections.push('<b>' + esc(channelReport.channelLabel || channelReport.channelKey || 'Canal YouTube') + '</b>');
  if (!channelReport.channel) {
    sections.push('Estado: no conectado');
    sections.push('Canal esperado: ' + esc(channelReport.expectedChannelId || 'N/D'));
    continue;
  }
  const stats = channelReport.channel.statistics || {};
  if (channelReport.connected) sections.push('Estado: conectado');
  else if (channelReport.public_metrics) sections.push('Estado: metricas publicas disponibles; falta OAuth del canal para subir/Analytics');
  else sections.push('Estado: no conectado');
  sections.push('Canal: ' + esc(channelReport.channel.title || 'N/D'));
  sections.push('ID: ' + esc(channelReport.channel.id || 'N/D'));
  sections.push('Subs: ' + (stats.hiddenSubscriberCount ? 'ocultos' : (stats.subscriberCount ?? 'N/D')));
  sections.push('Vistas totales: ' + (stats.viewCount ?? 'N/D'));
  sections.push('Videos: ' + (stats.videoCount ?? 'N/D'));
  if (channelReport.analytics_7d?.rows?.length) {
    const totals = totalsFromRows(channelReport.analytics_7d.rows);
    sections.push('Ultimos 7 dias: ' + totals.views + ' vistas, ' + totals.likes + ' likes, ' + totals.comments + ' comentarios, +' + totals.subscribersGained + ' subs');
  } else if (channelReport.analytics_7d?.error) {
    sections.push('Analytics 7d: requiere OAuth valido del canal');
  } else {
    sections.push('Ultimos 7 dias: sin datos recientes disponibles todavia');
  }
}

sections.push(
  '',
  '<b>Reglas operativas</b>',
  'Facebook: deshabilitado temporalmente; no se generan posts ni se publican Reels.',
  'YouTube: Vida con Dios y Fans Peliculas y Novelas conectados con permiso de subida.',
  'TikTok: manual solo para Vida con Dios.',
  '',
  telegramReady ? 'Telegram: configurado' : 'Telegram: falta TELEGRAM_BOT_TOKEN y/o TELEGRAM_CHAT_ID en .env'
);

return [{ json: { date, telegramReady, youtube, message: sections.join('\n') } }];

const item = $input.first()?.json || {};
if (item.error) {
  return [{ json: { youtube: { connected: false, error: item.error.message || item.error } } }];
}
return [{ json: { youtube: item } }];
